             if (JournalImpl.isInvalidSize(journalFileSize, wholeFileBuffer.position(), DataConstants.SIZE_INT)) {
                reader.markAsDataFile(file);

                wholeFileBuffer.position(pos + 1);
                // II - Ignore this record, let's keep looking
                continue;
             }

