             long transactionID = 0;

             if (JournalImpl.isTransaction(recordType)) {
                if (JournalImpl.isInvalidSize(journalFileSize, wholeFileBuffer.position(), DataConstants.SIZE_LONG)) {
                   wholeFileBuffer.position(pos + 1);
